// Renders the docs from window.TOKENS (generated by scripts/build.mjs) and drives the playground.
(() => {
  const T = window.TOKENS;
  const entries = Object.entries(T).map(([path, t]) => ({ path, ...t }));
  const $ = (s, r = document) => r.querySelector(s);
  const h = (tag, attrs = {}, ...kids) => {
    const e = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k === "style" && typeof v === "object") Object.assign(e.style, v);
      else if (k.startsWith("on")) e.addEventListener(k.slice(2), v);
      else if (v !== false && v != null) e.setAttribute(k, v);
    }
    for (const kid of kids.flat()) if (kid != null) e.append(kid.nodeType ? kid : document.createTextNode(kid));
    return e;
  };
  const by = (re) => entries.filter((e) => re.test(e.path));
  const last = (p) => p.split(".").pop();
  const num = (s) => parseFloat(String(s).replace(/[^\d.-]/g, ""));
  const rank = (a, b) => num(last(a.path)) - num(last(b.path)) || last(a.path).localeCompare(last(b.path));

  // ── copy ────────────────────────────────────────────────
  const toast = $("#toast");
  let toastTimer;
  const say = (msg) => { toast.textContent = msg; toast.classList.add("show"); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove("show"), 1600); };
  const copy = (text) => { (navigator.clipboard?.writeText(text) ?? Promise.reject()).then(() => say("Copied " + text), () => say(text)); };

  // ── overview ────────────────────────────────────────────
  const counts = entries.reduce((a, e) => ((a[e.status] = (a[e.status] || 0) + 1), a), {});
  $("#stats").append(
    ...[[entries.length, "tokens"], [counts.figma, "from Figma"], [counts.proposed, "proposed from the audit"], [counts.derived, "semantic and component"]]
      .map(([n, l]) => h("div", { class: "stat" }, h("b", {}, n), h("span", {}, l)))
  );

  // ── colour ──────────────────────────────────────────────
  const hex2rgb = (x) => [1, 3, 5].map((i) => parseInt(x.slice(i, i + 2), 16));
  const rgb2hex = (r) => "#" + r.map((v) => Math.round(v).toString(16).padStart(2, "0")).join("");
  const shortValue = (v) => { const m = /^rgba\((\d+), (\d+), (\d+), ([\d.]+)\)$/.exec(v); return m ? `${rgb2hex([+m[1], +m[2], +m[3]])} ${Math.round(m[4] * 100)}%` : v; };
  const swatch = (e, label) => h("button", { class: "swatch", title: e.css, onclick: () => copy(`var(${e.css})`) },
    h("span", { class: "chip", style: { display: "block", background: `var(${e.css})` } }),
    h("span", { class: "n" }, label ?? last(e.path), e.status === "proposed" ? h("span", { class: "dot", title: "Proposed: not in Figma" }) : null),
    h("span", { class: "v" }, shortValue(e.value)));
  const primitives = by(/^color\.(white|black|blue|neutral|red|cyan|sky|orange)/);
  const families = [["base", primitives.filter((e) => /^color\.(white|black)$/.test(e.path))]];
  for (const f of ["blue", "neutral", "red", "cyan", "sky", "orange"]) families.push([f, primitives.filter((e) => e.path.startsWith("color." + f + ".")).sort(rank)]);
  $("#primitives").append(...families.map(([name, list]) => h("div", { class: "family" }, h("h4", {}, name), h("div", { class: "ramp" }, list.map((e) => swatch(e, name === "base" ? last(e.path) : last(e.path)))))));

  const roles = ["text", "surface", "border", "action", "feedback", "effect"];
  $("#semantic").append(h("table", {},
    h("thead", {}, h("tr", {}, h("th"), h("th", {}, "Token"), h("th", {}, "CSS variable"), h("th", {}, "Points at"), h("th", {}, "Use"))),
    h("tbody", {}, roles.flatMap((r) => by(new RegExp(`^color\\.${r}\\.`)).map((e) => h("tr", {},
      h("td", { class: "sw" }, h("i", { style: { background: `var(${e.css})` } })),
      h("td", {}, e.path),
      h("td", {}, h("code", { style: { cursor: "pointer" }, onclick: () => copy(`var(${e.css})`) }, e.css)),
      h("td", { class: "alias" }, e.alias ?? e.value),
      h("td", {}, e.description ?? "")))))));
  $("#m3").append(h("div", { class: "ramp" }, by(/^color\.m3\./).map((e) => swatch(e, last(e.path)))));

  // ── type ────────────────────────────────────────────────
  const styleNames = [...new Set(by(/^text\./).map((e) => e.path.split(".")[1]))];
  const SAMPLE = "Ask once. See how every AI thinks.";
  $("#styles").append(...styleNames.map((n) => {
    const g = (k) => T[`text.${n}.${k}`];
    const v = (k) => `var(${g(k).css})`;
    return h("div", { class: "spec" },
      h("div", { class: "meta" }, h("b", {}, n), h("span", {}, `${g("size").value} / ${g("line").value} · ${g("weight").value} · ${g("tracking").value}`)),
      h("div", {}, h("div", { class: "sample", style: { fontSize: v("size"), lineHeight: v("line"), fontWeight: v("weight"), letterSpacing: v("tracking") } }, SAMPLE),
        h("div", { class: "note" }, T[`text.${n}.size`].description || "")));
  }));
  const sizes = by(/^size\.font\./).sort(rank);
  $("#sizes").append(...sizes.map((e) => h("div", { class: "bar-row" }, h("span", { class: "lbl" }, `${last(e.path)}  ${e.value}`), h("span", { class: "bar", style: { width: `calc(${num(e.value)} * 6px)`, height: "8px" } }), h("span", { class: "lbl" }, ""))));

  // ── space, control, radius ──────────────────────────────
  const spaces = by(/^size\.space\./).sort(rank);
  $("#spaces").append(...spaces.map((e) => h("div", { class: "bar-row" }, h("span", { class: "lbl" }, `space-${e.css.replace("--space-", "")}  ${e.value}`), h("span", { class: "bar", style: { width: `var(${e.css})` } }), h("span", { class: "lbl" }, ""))));
  $("#controls").append(...by(/^size\.control\./).map((e) => h("div", { class: "box" }, h("div", { class: "demo", style: { width: `var(${e.css})`, height: `var(${e.css})`, borderRadius: "var(--radius-sm)" } }), h("b", {}, last(e.path)), h("span", {}, e.value), h("span", {}, e.note ?? ""))));
  $("#radii").append(...by(/^radius\./).map((e) => h("div", { class: "box" }, h("div", { class: "demo", style: { borderRadius: `var(${e.css})` } }), h("b", {}, last(e.path)), h("span", {}, e.value === "9999px" ? "pill" : e.value), h("span", {}, e.consolidates ? "absorbs " + e.consolidates.join(", ") : ""))));

  // ── elevation and states ────────────────────────────────
  $("#shadows").append(...by(/^shadow\./).map((e) => h("div", { class: "box" }, h("div", { class: "demo plain", style: { borderRadius: "var(--radius-md)", boxShadow: `var(${e.css})` } }), h("b", {}, last(e.path)), h("span", {}, e.description ?? ""))),
    h("div", { class: "box" }, h("div", { class: "demo plain", style: { borderRadius: "var(--radius-pill)", boxShadow: "var(--focus-halo)", borderColor: "var(--focus-ring-color)" } }), h("b", {}, "focus halo"), h("span", {}, "Focused search")));
  $("#states").append(...by(/^state\./).map((e) => h("div", { class: "box" }, h("div", { class: "demo", style: { borderRadius: "var(--radius-md)", background: "var(--color-blue-600)", opacity: `var(${e.css})`, border: 0 } }), h("b", {}, last(e.path)), h("span", {}, e.value))));

  // ── motion ──────────────────────────────────────────────
  let ease = "--ease-standard";
  const easeBtns = by(/^ease\./).map((e) => h("button", { class: "pill-btn", "aria-pressed": e.css === ease, title: e.value, onclick: (ev) => { ease = e.css; easeBtns.forEach((b) => b.setAttribute("aria-pressed", b === ev.currentTarget)); } }, last(e.path)));
  $("#eases").append(...easeBtns);
  $("#durations").append(...by(/^duration\./).sort((a, b) => num(a.value) - num(b.value)).map((e) => {
    const track = h("div", { class: "track" }, h("div", { class: "dot" }));
    const play = () => {
      track.style.setProperty("--track-w", track.clientWidth + "px");
      track.firstChild.style.transition = "none"; track.classList.remove("go"); void track.offsetWidth;
      track.firstChild.style.transition = `transform var(${e.css}) var(${ease})`; track.classList.add("go");
      setTimeout(() => track.classList.remove("go"), num(e.value) + 700);
    };
    return h("div", { class: "motion-row" }, h("span", { class: "lbl" }, `${last(e.path)}  ${e.value}`), track, h("button", { class: "pill-btn", onclick: play }, "Play"));
  }));

  // ── layers and audit tables ─────────────────────────────
  $("#layersTable").append(h("table", {}, h("thead", {}, h("tr", {}, h("th", {}, "Token"), h("th", {}, "Value"), h("th", {}, "Where it came from"))),
    h("tbody", {}, by(/^(z|breakpoint)\./).map((e) => h("tr", {}, h("td", {}, h("code", {}, e.css)), h("td", {}, e.value), h("td", {}, e.audit ?? e.note ?? ""))))));

  const kinds = { All: /.*/, Colour: /^color\./, Type: /^(size\.font|font\.)/, Space: /^size\.(space|control)/, Radius: /^radius\./, Elevation: /^shadow\./, Motion: /^(duration|ease)\./, Layers: /^(z|breakpoint)\./ };
  const proposed = entries.filter((e) => e.status === "proposed");
  let kind = "All";
  const renderAudit = () => {
    const rows = proposed.filter((e) => kinds[kind].test(e.path));
    $("#auditTable").replaceChildren(h("table", {}, h("thead", {}, h("tr", {}, h("th", {}, "Token"), h("th", {}, "Value"), h("th", {}, "What the code did"), h("th", {}, "Absorbs"))),
      h("tbody", {}, rows.map((e) => h("tr", {}, h("td", {}, h("code", {}, e.css)), h("td", {}, e.value.length > 40 ? e.value.slice(0, 38) + "…" : e.value), h("td", {}, e.audit ?? e.note ?? e.description ?? ""), h("td", {}, e.consolidates ? e.consolidates.join(", ") : ""))))));
    $("#auditCount").textContent = `${rows.length} of ${proposed.length} proposed tokens`;
  };
  $("#auditFilters").append(...Object.keys(kinds).map((k) => h("button", { class: "pill-btn", "aria-pressed": k === kind, onclick: (ev) => { kind = k; [...$("#auditFilters").children].forEach((b) => b.setAttribute("aria-pressed", b === ev.currentTarget)); renderAudit(); } }, k)), h("span", { class: "note", id: "auditCount", style: { alignSelf: "center", margin: 0 } }));
  renderAudit();

  // ── accessibility ───────────────────────────────────────
  const A = window.A11Y;
  if (A) {
    const R = A.results, cnt = (st) => R.filter((r) => r.status === st).length;
    $("#a11yStats").append(...[[R.length, "pairs measured"], [cnt("pass"), "pass"], [cnt("waived"), "waived, with a reason"], [cnt("fail"), "fail"]].map(([n, l]) => h("div", { class: "stat" }, h("b", {}, n), h("span", {}, l))));
    const kinds = ["All", ...new Set(R.map((r) => r.kind))]; let kind = "All", only = false;
    const draw = () => {
      const rows = R.filter((r) => (kind === "All" || r.kind === kind) && (!only || r.status !== "pass")).sort((a, b) => a.ratio - b.ratio);
      $("#a11yTable").replaceChildren(h("table", {}, h("thead", {}, h("tr", {}, h("th", {}, "Pair"), h("th", {}, "Kind"), h("th", {}, "Ratio"), h("th", {}, "Needs"), h("th", {}, "Result"))),
        h("tbody", {}, rows.map((r) => h("tr", {},
          h("td", {}, h("span", { class: "pair" }, h("i", { style: { background: `var(${T[r.bg].css})`, color: `var(${T[r.fg].css})` } }, "Aa"), `${r.fg.replace("color.", "")} on ${r.bg.replace("color.", "")}`)),
          h("td", {}, r.kind), h("td", { class: "mono" }, r.ratio.toFixed(2) + ":1"), h("td", { class: "mono" }, r.min + ":1"), h("td", {}, h("span", { class: "tag " + r.status }, r.status)))))));
    };
    $("#a11yFilters").append(...kinds.map((k) => h("button", { class: "pill-btn", "aria-pressed": k === kind, onclick: (ev) => { kind = k; [...$("#a11yFilters").children].filter((b) => b.dataset.f !== "1").forEach((b) => b.setAttribute("aria-pressed", b === ev.currentTarget)); draw(); } }, k)),
      h("button", { class: "pill-btn", "data-f": "1", "aria-pressed": false, onclick: (ev) => { only = !only; ev.currentTarget.setAttribute("aria-pressed", only); draw(); } }, "Only exceptions"));
    draw();
    const open = R.filter((r) => r.status === "waived" && r.waiver === "open");
    $("#a11yOpen").append(...(open.length ? open.map((r) => h("div", { class: "callout" }, h("b", {}, `${r.fg.replace("color.", "")} on ${r.bg.replace("color.", "")}: ${r.ratio.toFixed(2)}:1`), h("span", {}, r.reason))) : [h("p", { class: "note" }, "No open decisions.")]));
  }

  // ── playground ──────────────────────────────────────────
  const mix = (hex, to, t) => rgb2hex(hex2rgb(hex).map((v, i) => v + (to[i] - v) * t));
  const W = [255, 255, 255], K = [0, 0, 0];
  // Fractions reproduce the Figma blue ramp from #2979ff (700 to 1000 match exactly).
  const ramp = { 25: [W, 0.94], 50: [W, 0.965], 75: [W, 0.9], 100: [W, 0.8], 200: [W, 0.67], 300: [W, 0.5], 400: [W, 0.33], 500: [W, 0.17], 650: [K, 0.1], 700: [K, 0.33], 800: [K, 0.5], 900: [K, 0.67], 1000: [K, 0.8] };
  const iframes = [];
  const targets = () => [document.documentElement, ...iframes.map((f) => { try { return f.contentDocument.documentElement; } catch { return null; } }).filter(Boolean)];
  const set = (name, v) => targets().forEach((t) => t.style.setProperty(name, v));
  const clear = (name) => targets().forEach((t) => t.style.removeProperty(name));
  const applied = new Map();
  const put = (name, v) => { applied.set(name, v); set(name, v); };
  const drop = (name) => { applied.delete(name); clear(name); };
  const scaled = (re, k, fmt = (v) => v + "px") => by(re).forEach((e) => { const b = num(e.value); if (b === 0 || e.value === "9999px" || e.value === "50%") return; k === 1 ? drop(e.css) : put(e.css, fmt(+(b * k).toFixed(2))); });

  const brandEl = $("#cBrand");
  const applyBrand = () => {
    const base = brandEl.value; $("#oBrand").textContent = base;
    if (base.toLowerCase() === "#2979ff") { put("--color-blue-600", base); applied.delete("--color-blue-600"); clear("--color-blue-600"); for (const k of Object.keys(ramp)) drop(`--color-blue-${k}`); }
    else { put("--color-blue-600", base); for (const [k, [to, t]] of Object.entries(ramp)) put(`--color-blue-${k}`, mix(base, to, t)); }
    render();
  };
  const controls = [["cRadius", "oRadius", () => scaled(/^radius\./, +$("#cRadius").value), (v) => v.toFixed(1) + "×"],
                    ["cType", "oType", () => scaled(/^size\.font\./, +$("#cType").value), (v) => v.toFixed(2) + "×"],
                    ["cSpace", "oSpace", () => scaled(/^size\.space\./, +$("#cSpace").value), (v) => v.toFixed(2) + "×"]];
  const render = () => { $("#overrides").textContent = applied.size ? ":root {\n" + [...applied].map(([k, v]) => `  ${k}: ${v};`).join("\n") + "\n}" : "No overrides"; };
  brandEl.addEventListener("input", applyBrand);
  for (const [id, out, run, fmt] of controls) $("#" + id).addEventListener("input", () => { $("#" + out).textContent = fmt(+$("#" + id).value); run(); render(); });
  const reapply = (t) => applied.forEach((v, k) => t.style.setProperty(k, v));
  $("#bReset").addEventListener("click", () => { [...applied.keys()].forEach(drop); brandEl.value = "#2979ff"; $("#cRadius").value = 1; $("#cType").value = 1; $("#cSpace").value = 1; controls.forEach(([id, out, , fmt]) => ($("#" + out).textContent = fmt(1))); $("#oBrand").textContent = "#2979ff"; render(); });
  $("#bCopy").addEventListener("click", () => copy($("#overrides").textContent));

  // ── product previews (need a server that exposes the sibling prototype folders) ──
  const previews = [["frameWeb", "failWeb", "../../internetio-website/"], ["frameApp", "failApp", "../../internetio-mobile-prototype/?reset"]];
  const fit = () => previews.forEach(([fid]) => {
    const fr = $("#" + fid), f = fr.querySelector("iframe"); if (!f) return;
    const w = +fr.dataset.w, ht = +fr.dataset.h, s = fr.clientWidth / w;
    f.style.width = w + "px"; f.style.height = ht + "px"; f.style.transform = `scale(${s})`; fr.style.height = ht * s + "px";
  });
  previews.forEach(([fid, failId, src]) => {
    const fr = $("#" + fid);
    const f = h("iframe", { src, title: fid === "frameWeb" ? "Landing page" : "App", loading: "lazy" });
    f.addEventListener("load", () => {
      try { reapply(f.contentDocument.documentElement); iframes.includes(f) || iframes.push(f); }
      catch { $("#" + failId).hidden = false; $("#" + failId).textContent = "Cannot reach this product from here."; f.remove(); }
      fit();
    });
    fr.prepend(f); iframes.push(f);
  });
  window.addEventListener("resize", fit); fit();
  $("#previewNote").textContent = location.protocol === "file:"
    ? "Opened from disk, so the previews are blocked. Run `npm run docs` and open the printed address to see both products respond."
    : "Previews load ../../internetio-website and ../../internetio-mobile-prototype. Serve the prototypes folder (npm run docs) so both resolve.";
})();
